  AUTHORITATIVE_MAPPING,
  checkDrift,
  checkExportsDrift,
  deriveExpectedExports,
  discoverReferencePagePaths,
  EXCLUDED_REFERENCE_PAGES,
  type PackageMapping,
  parseDocContent,
  validateReferencePageCoverage,
} from './check-exports-drift.ts';

